  function frag(html) { var t = D.createElement('template'); t.innerHTML = html; return t.content; }
  function mark(n) { n.__hs = 1; var l = n.querySelectorAll ? n.querySelectorAll('*') : []; for (var i = 0; i < l.length; i++) l[i].__hs = 1; return n; }
  function record(html) { N++; return mark(frag(WRAP[0] + 'rec9' + ('0000000000' + N).slice(-11) + WRAP[1] + html + WRAP[2]).firstChild); }
  function own(n) { return n && n.__hs === 1; }
  function after(el) { var n = el.nextSibling; while (n && own(n)) n = n.nextSibling; return n; }
  function closed() { var A = D.getElementById('allrecords'); return !!A && (!!after(A) || D.readyState !== 'loading'); }
  function passed(id) { var el = D.getElementById(id); return !!el && (!!after(el) || D.readyState !== 'loading'); }
